import{_ as e,o as n,c as t,a3 as i}from"./chunks/framework.BlfGB29P.js";const p=JSON.parse('{"title":"Agent 与 LangChain","description":"建立 Agent 的控制模型，并从框架无关循环过渡到最小 LangChain Agent。","frontmatter":{"title":"Agent 与 LangChain","description":"建立 Agent 的控制模型，并从框架无关循环过渡到最小 LangChain Agent。"},"headers":[],"relativePath":"py-agent/agent/agent-langchain/index.md","filePath":"py-agent/agent/agent-langchain/index.md","lastUpdated":1785314595000}'),l={name:"py-agent/agent/agent-langchain/index.md"};function g(o,a,r,h,c,d){return n(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="agent-与-langchain" tabindex="-1">Agent 与 LangChain <a class="header-anchor" href="#agent-与-langchain" aria-label="Permalink to &quot;Agent 与 LangChain&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>本分组先回答“什么时候需要 Agent”，再解释模型与工具如何形成循环，最后把同一机制映射到 LangChain。重点是控制权和停止条件，不是先记框架 API。</p><h2 id="_1-学习目标" tabindex="-1">1. 学习目标 <a class="header-anchor" href="#_1-学习目标" aria-label="Permalink to &quot;1. 学习目标&quot;">​</a></h2><p>完成后，你应该能够：</p><ol><li>区分直接模型调用、Workflow 与 Agent；</li><li>解释推理、行动、观察和终止的完整循环；</li><li>识别 Agent 的循环、成本和副作用风险；</li><li>使用 LangChain 构建并观察一个最小工具型 Agent。</li></ol><h2 id="_2-文章顺序" tabindex="-1">2. 文章顺序 <a class="header-anchor" href="#_2-文章顺序" aria-label="Permalink to &quot;2. 文章顺序&quot;">​</a></h2><ol><li><a href="/py-agent/agent/agent-langchain/agent-vs-workflow">Agent 与 Workflow</a>：用控制流归属判断方案。</li><li><a href="/py-agent/agent/agent-langchain/agent-execution-loop">Agent 执行循环</a>：用框架无关模型理解一次完整运行。</li><li><a href="/py-agent/agent/agent-langchain/first-langchain-agent">第一个 LangChain Agent</a>：将循环映射为 <code>create_agent()</code>、消息与工具。</li></ol><h2 id="_3-分组边界" tabindex="-1">3. 分组边界 <a class="header-anchor" href="#_3-分组边界" aria-label="Permalink to &quot;3. 分组边界&quot;">​</a></h2><p>本组只建立最小运行模型。Chat Models、消息对象和结构化输出在下一组展开；State、流式调用和 Middleware 在后续分组系统讲解。</p>',10)])])}const _=e(l,[["render",g]]);export{p as __pageData,_ as default};
